final class SavedAudio: Hashable {
    let id: Int
    var isDownloaded: Bool
    init(id: Int, isDownloaded: Bool) {
        self.id = id
        self.isDownloaded = isDownloaded
    }
    static func == (lhs: SavedAudio, rhs: SavedAudio) -> Bool {
        lhs.id == rhs.id
    }
    func hash(into hasher: inout Hasher) { hasher.combine(id) }
}
let first = SavedAudio(id: 24, isDownloaded: false)
let second = SavedAudio(id: 24, isDownloaded: true)
print(first === second)
print(first == second)
var saved: Set<SavedAudio> = [first]
first.isDownloaded = true
print(saved.contains(second))
print(saved.remove(second) != nil)
print(saved.isEmpty)

Вывод false, true, true, true, true. Правило перенесено на статус загрузки: он меняется, но не входит в стабильный ключ урока.
